import { createMemo, JSX, ParentComponent, Show } from "solid-js";

import { Button } from "#core/ui-next/components/button.jsx";
import { Filigree } from "#core/ui-next/components/filigree.jsx";
import { ModalFrame } from "#core/ui-next/components/modal-frame.jsx";
import { Popup, usePopupContext } from "#core/ui-next/components/popup.jsx";
import { HSlot } from "#core/ui-next/components/slot.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";

export interface ConfirmationDialogProps {
	/** The name of the tooltip. This is used for triggers and querries so it is not reactive and should not be changed after being set */
	name: string;

	/** The text to show on the accept button. Default: LOC_GENERIC_OK */
	acceptText?: string;

	/** The handler that gets called when this popup is accept */
	onAccept?: () => void;

	/** The text to show on the cancel button.  Default: LOC_GENERIC_CANCEL */
	cancelText?: string;

	/** The handler that gets called when this popup is canceled */
	onCancel?: () => void;

	/** The title to display in the popup */
	title?: JSX.Element;

	/** The content to display in the popup */
	content?: JSX.Element;

	/** Should this popup be auto-accepted and not shown? */
	autoAccept?: boolean;
}

const ConfirmationDialogComponent: ParentComponent<ConfirmationDialogProps> = (props) => {
	const context = usePopupContext();

	let accepted = false;
	const name = createMemo(() => `confirmation-dialog-${props.name}`);
	const acceptText = createMemo(() => props.acceptText ?? "LOC_GENERIC_OK");
	const cancelText = createMemo(() => props.acceptText ?? "LOC_GENERIC_CANCEL");

	const close = () => context.close(name());

	function handleAccept() {
		accepted = true;
		close();
	}

	function handleCancel() {
		close();
	}

	function handleOpen() {
		if (props.autoAccept) {
			handleAccept();
		}
	}

	function handleClose() {
		if (!accepted) {
			props.onCancel?.();
		} else {
			props.onAccept?.();
		}
	}

	return (
		<>
			<Popup.Trigger name={name()}>{props.children}</Popup.Trigger>
			<Popup.Item
				onOpen={handleOpen}
				onClose={handleClose}
				name={name()}
			>
				<ModalFrame>
					<div class="font-title text-secondary text-xl m-1 uppercase">{props.title}</div>
					<Filigree.H2 class="mb-2" />
					<Show when={props.content}>
						<div class="m-2 font-body text-accent-2 text-base">{props.content}</div>
					</Show>
					<HSlot class="flex flex-row items-center justify-=center">
						<Button
							class="flex-2 m-2"
							onActivate={handleAccept}
						>
							{acceptText()}
						</Button>
						<Button
							class="flex-2 m-2"
							onActivate={handleCancel}
						>
							{cancelText()}
						</Button>
					</HSlot>
				</ModalFrame>
			</Popup.Item>
		</>
	);
};

export const ConfirmationDialog = ComponentRegistry.register({
	name: "ConfirmationDialog",
	createInstance: ConfirmationDialogComponent,
});
